<script>
import api from '../api.js';
export default {name:'ConfigAudit',props:{project:String,target:String},emits:['close'],data(){return {data:null,error:'',busy:false,selected:null}},async mounted(){this.busy=true;try{this.data=await api.request('/resolved-view',{project:this.project,target:this.target})}catch(e){this.error=e.message}finally{this.busy=false}},methods:{text(v){return JSON.stringify(v,null,2)},support(f){return {native:'Нативный обработчик',raw:'Только исходное значение',unsupported:'Не перенесён'}[f.support]||f.support}}};
</script>
<template>
<div class="modal-backdrop" @click.self="$emit('close')"><section class="modal config-audit" role="dialog" aria-modal="true" aria-labelledby="audit-title"><header><div><small>WIDGET CONFIG · RESOLVED VIEW</small><h2 id="audit-title">Источник колонок</h2></div><button aria-label="Закрыть проверку конфигурации" @click="$emit('close')">×</button></header><div class="audit-scroll"><p v-if="busy">Разрешение конфигурации TACTIC…</p><p v-if="error" class="error">{{error}}</p><template v-if="data"><p><code>{{data.search_type}} · {{data.view}}</code><span v-if="data.resolved_view!==data.view"> → {{data.resolved_view}}</span></p><p class="notice">{{data.notice}}</p><h3>Слои в порядке приоритета</h3><ol class="config-layers"><li v-for="layer in data.layers" :key="layer.index"><code>{{layer.view}}</code> — {{layer.origin}}</li></ol><details><summary>Параметры таблицы и сортировка</summary><pre>{{text({options:data.options,ui:data.table_options,sort:data.default_sort})}}</pre></details><p v-if="data.sort_error" class="error">{{data.sort_error}}</p><h3>Колонки в разрешённом порядке</h3><div class="audit-fields"><button v-for="f in data.fields" :key="f.name" :class="{active:selected===f.name}" @click="selected=f.name"><strong>{{f.label}}</strong><code>{{f.name}}</code><span :class="{warning:f.support!=='native'}">{{support(f)}}</span></button></div><template v-for="f in data.fields.filter(f=>f.name===selected)" :key="f.name"><h3>{{f.label}}</h3><dl class="audit-definition"><dt>Display handler</dt><dd><code>{{f.display_handler||'Штатный default по layout/типу колонки'}}</code></dd><dt>Edit handler</dt><dd><code>{{f.edit_handler||'Определяется edit-view'}}</code></dd><dt>Action</dt><dd><code>{{f.action||'Default action исходного вида'}}</code></dd><dt>Состояние</dt><dd>{{support(f)}}<p v-if="f.reason">{{f.reason}}</p></dd></dl><pre>{{text({options:f.options,attributes:f.attributes,sort:{allowed:f.sortable,reason:f.sort_reason},sources:f.sources})}}</pre></template></template></div><footer><button @click="$emit('close')">Закрыть</button></footer></section></div>
</template>
